#include <iostream>
#include <string>
using namespace std;

struct Node {
    char ch;
    Node *left, *right;
    Node(char c) : ch(c), left(nullptr), right(nullptr) {}
};

string s;
int pos = 0;

Node* build() {
    if (pos >= (int)s.size()) return nullptr;
    char c = s[pos++];
    if (c == '#') return nullptr;
    Node *p = new Node(c);
    p->left = build();
    p->right = build();
    return p;
}

void inorder(Node *p) {
    if (p == nullptr) return;
    inorder(p->left);
    cout << p->ch << ' ';
    inorder(p->right);
}

int main() {
    if (!(cin >> s)) return 0;
    Node *root = build();
    inorder(root);
    cout << "\n";
    return 0;
}
